def second_largest(nums):
    s = sorted(set(nums), reverse=True)
    return s[1] if len(s) > 1 else None

def is_palindrome(s):
    t = [c.lower() for c in s if c.isalnum()]
    return t == t[::-1]

def flatten(lst):
    out = []
    for x in lst:
        if isinstance(x, list):
            out.extend(flatten(x))
        else:
            out.append(x)
    return out

def rle(s):
    out, i = '', 0
    while i < len(s):
        j = i
        while j < len(s) and s[j] == s[i]:
            j += 1
        out += s[i] + str(j - i)
        i = j
    return out

def roman_to_int(s):
    v = {'I':1,'V':5,'X':10,'L':50,'C':100,'D':500,'M':1000}
    t = 0
    for i, c in enumerate(s):
        t += -v[c] if i + 1 < len(s) and v[c] < v[s[i+1]] else v[c]
    return t

def valid_brackets(s):
    pairs = {')':'(', ']':'[', '}':'{'}
    st = []
    for c in s:
        if c in '([{':
            st.append(c)
        elif not st or st.pop() != pairs[c]:
            return False
    return not st

def two_sum(nums, target):
    for i in range(len(nums)):
        for j in range(i + 1, len(nums)):
            if nums[i] + nums[j] == target:
                return (i, j)
    return None

def merge_intervals(iv):
    out = []
    for a, b in sorted(iv):
        if out and a <= out[-1][1]:
            out[-1][1] = max(out[-1][1], b)
        else:
            out.append([a, b])
    return out

def group_anagrams(words):
    d = {}
    for w in words:
        d.setdefault(''.join(sorted(w)), []).append(w)
    return sorted((sorted(g) for g in d.values()), key=lambda g: g[0])

def longest_common_prefix(strs):
    if not strs:
        return ''
    p = strs[0]
    for s in strs[1:]:
        while not s.startswith(p):
            p = p[:-1]
    return p

def rotate_right(lst, k):
    if not lst:
        return []
    k %= len(lst)
    return lst[-k:] + lst[:-k] if k else list(lst)

from math import gcd
def lcm_list(nums):
    r = 1
    for n in nums:
        r = r * n // gcd(r, n)
    return r

def binary_search(arr, x):
    lo, hi = 0, len(arr)
    while lo < hi:
        m = (lo + hi) // 2
        if arr[m] < x:
            lo = m + 1
        else:
            hi = m
    return lo if lo < len(arr) and arr[lo] == x else -1

def max_subarray(nums):
    best = cur = nums[0]
    for x in nums[1:]:
        cur = max(x, cur + x)
        best = max(best, cur)
    return best

def dedupe(lst):
    out = []
    for x in lst:
        if not any(type(x) == type(y) and x == y for y in out):
            out.append(x)
    return out

def valid_ipv4(s):
    p = s.split('.')
    return len(p) == 4 and all(x.isdigit() and x.isascii() and int(x) <= 255 and (x == '0' or not x.startswith('0')) for x in p)
